/*!
 * Minimal Jekyll Theme for Acad-Homepage
 * Based on the acad-homepage template by RayeRen
 */

(function() {
  'use strict';

  // Greedy Navigation
  var $nav = document.querySelector('.greedy-nav');
  if ($nav) {
    var $btn = $nav.querySelector('button');
    var $visibleLinks = $nav.querySelector('.visible-links');
    var $hiddenLinks = $nav.querySelector('.hidden-links');
    var breaks = [];

    function updateNav() {
      var availableSpace = $btn.offsetWidth - 20;
      var spaceUsed = 0;
      var hiddenCount = 0;

      // Reset
      $hiddenLinks.innerHTML = '';
      $hiddenLinks.classList.remove('hidden');

      // Measure all visible links
      var children = Array.from($visibleLinks.children);
      for (var i = 0; i < children.length; i++) {
        var child = children[i];
        if (i === 0) continue; // skip Homepage link
        if (spaceUsed + child.offsetWidth > availableSpace) {
          // Move to hidden
          $hiddenLinks.appendChild(child.cloneNode(true));
          hiddenCount++;
        } else {
          spaceUsed += child.offsetWidth;
        }
      }

      if (hiddenCount > 0) {
        $btn.style.display = '';
        $hiddenLinks.classList.add('hidden');
      } else {
        $btn.style.display = 'none';
      }
    }

    // Toggle hidden links
    $btn.addEventListener('click', function() {
      $hiddenLinks.classList.toggle('hidden');
    });

    window.addEventListener('resize', updateNav);
    updateNav();
  }

  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
    anchor.addEventListener('click', function(e) {
      var targetId = this.getAttribute('href');
      if (targetId && targetId !== '#') {
        e.preventDefault();
        var target = document.querySelector(targetId);
        if (target) {
          target.scrollIntoView({ behavior: 'smooth' });
        }
      }
    });
  });

})();
